import { load, YAML11_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('YAML 1.1 signed non-decimal integers resolve with sign and base', () => {
    assert.strictEqual(load('-010', { schema: YAML11_SCHEMA }), -8, '-010 is octal -8');
    assert.strictEqual(load('+010', { schema: YAML11_SCHEMA }), 8, '+010 is octal 8');
    assert.strictEqual(load('-0xFF', { schema: YAML11_SCHEMA }), -255, '-0xFF is -255');
    assert.strictEqual(load('-0b101', { schema: YAML11_SCHEMA }), -5, '-0b101 is -5');
    assert.strictEqual(load('-1:30', { schema: YAML11_SCHEMA }), -90, '-1:30 is sexagesimal -90');
  });
});
"}, "note": "Replacing the sign-stripping block with `if (false)` in the YAML 1.1 integer parser leaves the '-'/'+' prefix in the value, so signed octal, hex, binary, and sexagesimal forms are misparsed (e.g. load('-010', {schema: YAML11_SCHEMA}) now returns -10 instead of -8, and '-0xFF' returns -0 instead of -255). The default CORE schema is unaffected, which is why the existing suite still passes."}
